export const eventBus = new EventBus();

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  list(): User[] {
    return Array.from(this.users.values());
  }

  create(input: CreateUserInput): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  get(id: string): User | undefined {
    return this.users.get(id);
  }

  update(id: string, input: UpdateUserInput): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...input };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  list(): Project[] {
    return Array.from(this.projects.values());
  }

  create(input: CreateProjectInput): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.projects.set(id, project);
    return project;
  }

  get(id: string): Project | undefined {
    return this.projects.get(id);
  }

  update(id: string, input: UpdateProjectInput): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...input };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const proj = this.projects.get(projectId);
    if (!proj) return undefined;
    if (!proj.memberIds.includes(userId)) {
      proj.memberIds.push(userId);
    }
    return proj;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const proj = this.projects.get(projectId);
    if (!proj) return undefined;
    proj.memberIds = proj.memberIds.filter(id => id !== userId);
    return proj;
  }
}

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId?: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();

  listByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(t => t.projectId === projectId);
  }

  create(input: CreateTaskInput): Task {
    const id = randomUUID();
    const task: Task = { id, title: input.title, description: input.description, status: 'todo', projectId: input.projectId, assigneeId: null };
    this.tasks.set(id, task);
    return task;
  }

  get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  update(id: string, input: UpdateTaskInput): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...input };
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    const current = task.status;
    // enforce forward-only transitions: todo -> in-progress -> done
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const currentIndex = order.indexOf(current);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1 || newIndex < currentIndex || newIndex - currentIndex > 1) {
      throw new Error('Invalid status transition');
    }
    task.status = newStatus;
    this.tasks.set(id, task);
    eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId ?? null,
      oldStatus: current,
      newStatus: newStatus,
    });
    return task;
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    this.tasks.set(id, task);
    eventBus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: assigneeId,
    });
    return task;
  }
}

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO string
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  listByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(c => c.taskId === taskId);
  }

  create(input: CreateCommentInput, taskTitle?: string, authorName?: string): Comment {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const comment: Comment = { id, taskId: input.taskId, authorId: input.authorId, body: input.body, createdAt };
    this.comments.set(id, comment);

    // publish event for notification service. Note: Since services cannot call each other, we accept optional metadata (taskTitle, authorName)
    eventBus.publish('comment.added', {
      commentId: id,
      taskId: input.taskId,
      taskTitle: taskTitle ?? 'Unknown Task',
      authorId: input.authorId,
      authorName: authorName ?? 'Unknown User',
    });

    return comment;
  }

  get(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  delete(id: string): boolean {
    return this.comments.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor() {
    // subscribe to task and comment events
    eventBus.subscribe('task.assigned', (payload: any) => {
      const { taskId, taskTitle, assigneeId } = payload || {};
      if (!assigneeId) return;
      const message = `You have been assigned to task "${taskTitle}" (#${taskId}).`;
      this.create({ userId: assigneeId, message });
    });

    eventBus.subscribe('task.statusChanged', (payload: any) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload || {};
      if (!assigneeId) return; // notify assignee if exists
      const message = `Task "${taskTitle}" (#${taskId}) status changed from ${oldStatus} to ${newStatus}.`;
      this.create({ userId: assigneeId, message });
    });

    eventBus.subscribe('comment.added', (payload: any) => {
      const { commentId, taskId, taskTitle, authorId, authorName } = payload || {};
      // Notify the author themselves might not be useful; in a real system we'd notify watchers/assignee.
      // For simplicity, notify the author that their comment is recorded.
      const message = `${authorName} commented on task "${taskTitle}" (#${taskId}). Comment ID: ${commentId}.`;
      this.create({ userId: authorId, message });
    });
  }

  private create(input: { userId: string; message: string }): Notification {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const notif: Notification = { id, userId: input.userId, message: input.message, read: false, createdAt };
    this.notifications.set(id, notif);
    return notif;
  }

  listByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(n => n.userId === userId);
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    this.notifications.set(id, n);
    return n;
  }
}

import http, { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export interface APIDependencies {
  userService: UserService;
  projectService: ProjectService;
  taskService: TaskService;
  commentService: CommentService;
  notificationService: NotificationService;
}

function readJson<T = any>(req: IncomingMessage): Promise<T> {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => (data += chunk));
    req.on('end', () => {
      if (!data) return resolve({} as any);
      try {
        const parsed = JSON.parse(data);
        resolve(parsed);
      } catch (err) {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res: ServerResponse, status: number, body: any): void {
  const json = JSON.stringify(body);
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Length', Buffer.byteLength(json));
  res.end(json);
}

function sendNoContent(res: ServerResponse): void {
  res.statusCode = 204;
  res.end();
}

export function createServer(deps: APIDependencies): http.Server {
  const server = http.createServer(async (req, res) => {
    try {
      const method = req.method || 'GET';
      const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
      const path = url.pathname;

      // Routing
      if (path === '/users' && method === 'GET') {
        const users = deps.userService.list();
        return sendJson(res, 200, users);
      }
      if (path === '/users' && method === 'POST') {
        const body = await readJson(req);
        const user = deps.userService.create({ name: body.name, email: body.email });
        return sendJson(res, 201, user);
      }
      if (path.startsWith('/users/') ) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const user = deps.userService.get(id);
          if (!user) return sendJson(res, 404, { error: 'User not found' });
          return sendJson(res, 200, user);
        }
        if (method === 'PUT') {
          const body = await readJson(req);
          const updated = deps.userService.update(id, { name: body.name, email: body.email });
          if (!updated) return sendJson(res, 404, { error: 'User not found' });
          return sendJson(res, 200, updated);
        }
        if (method === 'DELETE') {
          const ok = deps.userService.delete(id);
          if (!ok) return sendJson(res, 404, { error: 'User not found' });
          return sendNoContent(res);
        }
      }

      if (path === '/projects' && method === 'GET') {
        const projects = deps.projectService.list();
        return sendJson(res, 200, projects);
      }
      if (path === '/projects' && method === 'POST') {
        const body = await readJson(req);
        const project = deps.projectService.create({ name: body.name, description: body.description });
        return sendJson(res, 201, project);
      }
      if (path.startsWith('/projects/') ) {
        const parts = path.split('/').filter(Boolean); // ['projects', id, 'members'?]
        const id = parts[1];
        if (parts.length === 2) {
          if (method === 'GET') {
            const project = deps.projectService.get(id);
            if (!project) return sendJson(res, 404, { error: 'Project not found' });
            return sendJson(res, 200, project);
          }
          if (method === 'PUT') {
            const body = await readJson(req);
            const updated = deps.projectService.update(id, { name: body.name, description: body.description });
            if (!updated) return sendJson(res, 404, { error: 'Project not found' });
            return sendJson(res, 200, updated);
          }
          if (method === 'DELETE') {
            const ok = deps.projectService.delete(id);
            if (!ok) return sendJson(res, 404, { error: 'Project not found' });
            return sendNoContent(res);
          }
        } else if (parts.length === 3 && parts[2] === 'members') {
          if (method === 'POST') {
            const body = await readJson(req);
            const updated = deps.projectService.addMember(id, body.userId);
            if (!updated) return sendJson(res, 404, { error: 'Project not found' });
            return sendJson(res, 200, updated);
          }
          if (method === 'DELETE') {
            const body = await readJson(req);
            const updated = deps.projectService.removeMember(id, body.userId);
            if (!updated) return sendJson(res, 404, { error: 'Project not found' });
            return sendJson(res, 200, updated);
          }
        }
      }

      if (path === '/tasks' && method === 'GET') {
        const projectId = url.searchParams.get('projectId');
        if (!projectId) return sendJson(res, 400, { error: 'projectId is required' });
        const tasks = deps.taskService.listByProject(projectId);
        return sendJson(res, 200, tasks);
      }
      if (path === '/tasks' && method === 'POST') {
        const body = await readJson(req);
        const task = deps.taskService.create({ title: body.title, description: body.description, projectId: body.projectId });
        return sendJson(res, 201, task);
      }
      if (path.startsWith('/tasks/')) {
        const parts = path.split('/').filter(Boolean); // ['tasks', id, maybe 'status'/'assign']
        const id = parts[1];
        if (parts.length === 2) {
          if (method === 'GET') {
            const task = deps.taskService.get(id);
            if (!task) return sendJson(res, 404, { error: 'Task not found' });
            return sendJson(res, 200, task);
          }
          if (method === 'PUT') {
            const body = await readJson(req);
            const updated = deps.taskService.update(id, { title: body.title, description: body.description });
            if (!updated) return sendJson(res, 404, { error: 'Task not found' });
            return sendJson(res, 200, updated);
          }
          if (method === 'DELETE') {
            const ok = deps.taskService.delete(id);
            if (!ok) return sendJson(res, 404, { error: 'Task not found' });
            return sendNoContent(res);
          }
        } else if (parts.length === 3 && parts[2] === 'status' && method === 'PUT') {
          const body = await readJson(req);
          try {
            const updated = deps.taskService.changeStatus(id, body.status as TaskStatus);
            if (!updated) return sendJson(res, 404, { error: 'Task not found' });
            return sendJson(res, 200, updated);
          } catch (err) {
            return sendJson(res, 400, { error: 'Invalid status transition' });
          }
        } else if (parts.length === 3 && parts[2] === 'assign' && method === 'PUT') {
          const body = await readJson(req);
          const updated = deps.taskService.assign(id, body.assigneeId);
          if (!updated) return sendJson(res, 404, { error: 'Task not found' });
          return sendJson(res, 200, updated);
        }
      }

      if (path === '/comments' && method === 'GET') {
        const taskId = url.searchParams.get('taskId');
        if (!taskId) return sendJson(res, 400, { error: 'taskId is required' });
        const comments = deps.commentService.listByTask(taskId);
        return sendJson(res, 200, comments);
      }
      if (path === '/comments' && method === 'POST') {
        const body = await readJson(req);
        const task = deps.taskService.get(body.taskId);
        const user = deps.userService.get(body.authorId);
        const comment = deps.commentService.create(
          { taskId: body.taskId, authorId: body.authorId, body: body.body },
          task?.title,
          user?.name
        );
        return sendJson(res, 201, comment);
      }
      if (path.startsWith('/comments/')) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const c = deps.commentService.get(id);
          if (!c) return sendJson(res, 404, { error: 'Comment not found' });
          return sendJson(res, 200, c);
        }
        if (method === 'DELETE') {
          const ok = deps.commentService.delete(id);
          if (!ok) return sendJson(res, 404, { error: 'Comment not found' });
          return sendNoContent(res);
        }
      }

      if (path === '/notifications' && method === 'GET') {
        const userId = url.searchParams.get('userId');
        if (!userId) return sendJson(res, 400, { error: 'userId is required' });
        const notifs = deps.notificationService.listByUser(userId);
        return sendJson(res, 200, notifs);
      }
      if (path.startsWith('/notifications/') && method === 'PUT') {
        const parts = path.split('/').filter(Boolean); // ['notifications', id, 'read']
        if (parts.length === 3 && parts[2] === 'read') {
          const id = parts[1];
          const updated = deps.notificationService.markRead(id);
          if (!updated) return sendJson(res, 404, { error: 'Notification not found' });
          return sendJson(res, 200, updated);
        }
      }

      // Fallback
      sendJson(res, 404, { error: 'Not found' });
    } catch (err: any) {
      if (!res.headersSent) {
        sendJson(res, 500, { error: err?.message || 'Internal Server Error' });
      } else {
        res.end();
      }
    }
  });
  return server;
}

